any_helpers:
fn contains_accepted_version(session: &Session, version: u64) -> bool {
    for entry in &session.entries {
        if entry.intent.accepted_version == version {
            return true;
        }
    }
    false
}

fn has_unapplied_sdk_through(session: &Session, version: u64) -> bool {
    for entry in &session.entries {
        if is_sdk_renewal(&entry.intent)
            && entry.intent.accepted_version <= version
            && entry.applied_deadline.is_none()
        {
            return true;
        }
    }
    false
}

renewal_roots:
use sandproof_protocol::lifecycle::{RenewalConfirmation, ConfirmedRenewal};

pub fn renewal_valid(result: &RenewalConfirmation) -> bool {
    result.is_sdk_renewal()
}

pub fn renewal_matches(result: &RenewalConfirmation, request: &AcceptedLifecycleIntent) -> bool {
    result.matches_request(request)
}

pub fn renewal_confirmed_matches(ack: &ConfirmedRenewal, result: &RenewalConfirmation) -> bool {
    ack.matches(result)
}
